SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·卷272·列传第三十一·杨业", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b013bdbee16ef533670c03ff4c90acd31095c6c8/content/books/zizhi-tongjian/vol-291/year-0952/part-03/sources/library/songshi-272-yangye-father/source.txt", "note": "《宋史》卷272·列传第三十一·杨业，段落 songshi-9c6e46fee832-p059005；已核上下文及传主，纸本及异文待核。", "id": "9b91f54f-4af8-556f-9d23-dc851ed22848"}, {"title": "新五代史·卷65·南汉世家第五·乾和十年蚝石之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b013bdbee16ef533670c03ff4c90acd31095c6c8/content/books/zizhi-tongjian/vol-291/year-0952/part-03/sources/library/xinwudaishi-65-haoshi-952/source.txt", "note": "《新五代史》卷65·南汉世家第五·乾和十年蚝石之战，段落 xin-wudaishi-b08f244b9241-p003287；已核上下文及传主，纸本及异文待核。", "id": "a1c6abe8-738c-5861-bd24-07fc252ca9bd"}, {"title": "资治通鉴·卷291·广顺二年十月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/tongjian-291-952-october/source.txt", "note": "《资治通鉴》卷291·广顺二年十月至十二月，段落 zizhi-tongjian-a63549944a71-p003454；已核上下文及传主，纸本及异文待核。", "id": "259474f3-6192-5096-9244-e7a279478f03"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年十一月荆南奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-november-952-hunan/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年十一月荆南奏报，段落 jiu-wudaishi-205deb4a7860-p002679；已核上下文及传主，纸本及异文待核。", "id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年十二月刘言奏报", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-december-952-hunan/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年十二月刘言奏报，段落 jiu-wudaishi-205deb4a7860-p002680；已核上下文及传主，纸本及异文待核。", "id": "ea816b38-74ec-5713-b766-d3cdf7ddf23a"}, {"title": "旧五代史·卷112·太祖本纪三·广顺三年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-january-953-yeji/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺三年正月，段落 jiu-wudaishi-205deb4a7860-p002681；已核上下文及传主，纸本及异文待核。", "id": "2d7ae78a-ac67-562a-aa5e-6b532a2abaee"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "侯章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，947年二月任都头，在陕州与王晏、赵晖共同谋划反抗契丹。生卒年暂未录入。", "biography": null, "status": "draft", "id": "aafc9da4-682f-5473-bedf-46c919bc77c8"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "潘崇彻", "aliases": ["潘崇徹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉内侍省丞。951年与谢贯率兵攻郴州，在义章击败南唐援军。《宋史》附传记为广州南海人，官称写内侍省局丞。生卒年尚未录入。", "biography": null, "status": "draft", "id": "782ac0d2-821f-5328-ba70-7c1c10b7902b"}, {"name": "徐台符", "aliases": ["徐臺符"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武强人，后晋金部郎中、知制诰。944年六月戊辰任翰林学士。生卒年本段未载。", "biography": null, "status": "draft", "id": "28c5a951-7fb9-591a-b527-988ede5145c7"}, {"name": "葛延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李屿的仆人，替李屿经营贩卖事务。948年与苏逢吉的仆人李澄合谋告发李屿谋反，李崧家族随后遭到诛杀。史书将此案记为冤案。生卒年尚未确定。", "biography": null, "status": "draft", "id": "811202de-9a8a-5ae0-b002-11da91b78d08"}, {"name": "李澄", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "苏逢吉的仆人。948年与葛延遇合谋告发李屿谋反，史书记载二人因此获赏，并将李崧家族遭诛记为冤案。生卒年尚未确定。", "biography": null, "status": "draft", "id": "c22adf9e-4986-598b-97e9-e91da5e89ee1"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "马希萼", "aliases": ["馬希萼"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希范的弟弟、马希广的兄长。947年马希范死时，任武平节度使、知永州事，部分将领主张拥立他，但最终马希广继位。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9d5be246-b5ae-553e-b5c5-a6a875b2c1cd"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "杨信（麟州刺史）", "aliases": ["楊信（麟州刺史）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "麟州地方豪强，曾自行担任刺史并获后周任命。去世后其子杨重训继任。《宋史》杨业传记杨业之父杨信为汉麟州刺史，按同地身份补充父子关系；不与安州节度使等同名者混同。生卒年未确。", "biography": null, "status": "draft", "id": "554961bd-3038-5871-ba37-52ce919cafe6"}, {"name": "杨重训", "aliases": ["楊重訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "麟州杨信之子，父死后继任刺史，曾以麟州归附北汉。952年遭围攻后重新归附后周，并向夏州、府州求援。生卒年未载。", "biography": null, "status": "draft", "id": "dcdd9a95-3e4c-5ef9-b6ad-d2f8afb9ae5f"}, {"name": "杨业", "aliases": ["楊業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《宋史》记其为并州太原人，父亲杨信任汉麟州刺史。年轻时以骑射和勇武见称，后事刘崇。此处只补充父子身份及有明确原文的早年背景，具体生卒与后续经历待逐段补录。", "biography": null, "status": "draft", "id": "56fb4cd6-4db6-5a6d-9142-471226802015"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
