": "48ca3ee4-cced-5056-8a47-4394d3ad6237", "event_id": "54c2772f-3a75-5221-8146-1b27fcab6e32"}, {"role": "援救郴州并判断湖南军疲惫、阵列不整", "status": "draft", "id": "bded8829-e4f5-54b9-8c9e-3781e87a083b", "person_id": "782ac0d2-821f-5328-ba70-7c1c10b7902b", "event_id": "726904bd-0623-5e99-ad93-747f55e33650"}, {"role": "发起攻击并击败湖南军", "status": "draft", "id": "a089ef86-198e-505c-8302-7c0d14ced73c", "person_id": "782ac0d2-821f-5328-ba70-7c1c10b7902b", "event_id": "a3583e3f-bdba-59ad-b8e0-fcba9c9036f7"}, {"role": "所率湖南军被南汉击败", "status": "draft", "id": "971a3461-b992-51d3-b051-34140e4773d0", "person_id": "48ca3ee4-cced-5056-8a47-4394d3ad6237", "event_id": "a3583e3f-bdba-59ad-b8e0-fcba9c9036f7"}, {"role": "请求处死诬告者", "status": "draft", "id": "76260f52-ff21-5e8d-901a-11c615185300", "person_id": "28c5a951-7fb9-591a-b527-988ede5145c7", "event_id": "7ff4ac62-373e-5b8c-a179-44bd2e8f60c3"}, {"role": "被徐台符请求追究诬告责任", "status": "draft", "id": "bb2c6d05-5879-57a1-955c-c4b735e08140", "person_id": "811202de-9a8a-5ae0-b002-11da91b78d08", "event_id": "7ff4ac62-373e-5b8c-a179-44bd2e8f60c3"}, {"role": "被徐台符请求追究诬告责任", "status": "draft", "id": "a4c65ac5-6c73-5a48-aa4b-83da34205552", "person_id": "c22adf9e-4986-598b-97e9-e91da5e89ee1", "event_id": "7ff4ac62-373e-5b8c-a179-44bd2e8f60c3"}, {"role": "以多次赦免为由反对追究处死", "status": "draft", "id": "dd8d0ae4-843c-574e-be9a-13dfb36ceff4", "person_id": "16b195e8-f15a-5814-bdd2-934f10bbdf39", "event_id": "1361cf91-40b3-5d12-ace4-c8b12d873a84"}, {"role": "支持徐台符的主张并报告郭威", "status": "draft", "id": "7d307d34-7369-5d9b-ae8f-743455060ef7", "person_id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2", "event_id": "1c457b26-99cf-5acd-adea-2ed4661b7923"}, {"role": "被后周逮捕并处死", "status": "draft", "id": "fe804d37-bf4a-5ac7-beed-63436b75c340", "person_id": "811202de-9a8a-5ae0-b002-11da91b78d08", "event_id": "addc589d-1d68-5d87-aa5d-9e0fc72defe0"}, {"role": "被后周逮捕并处死", "status": "draft", "id": "25afe5b2-46c3-5f77-a627-9f5eaf666212", "person_id": "c22adf9e-4986-598b-97e9-e91da5e89ee1", "event_