INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "郭威将折从阮从保义调任静难节度使，令其讨伐野鸡族。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：复用已有折从远主体及折从阮别名；此处仅记调任及任务，不推出已经战胜。", "status": "draft", "id": "f7308b5e-1b4b-55ee-b0c2-5e17b5a85ac4", "subject_id": "ed070086-92f8-56e7-91a2-9d0bdb869e20", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年十一月辛未", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "15a596dc-6518-5ce3-b01b-e4dcefc4a91f", "subject_id": "ed070086-92f8-56e7-91a2-9d0bdb869e20", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭威：调折从阮任静难节度使并令其讨伐。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "2df13aca-37c6-52d8-b48a-1fcf6d1c0a0e", "subject_id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：调折从阮任静难节度使并令其讨伐。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6f7b90f6-d2db-5885-b6c4-2a61d6fcb8c3", "subject_id": "f7c8fa45-4109-591c-8461-5a22842e0e81", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "person", "field_path": "description", "claim_text": "折从远：由保义调任静难节度使，受命讨伐野鸡族。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c40cbda8-7113-51e9-b41c-260f6f9d737c", "subject_id": "500d7480-2e3a-5553-9370-8e4295db3cc1", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "折从远：由保义调任静难节度使，受命讨伐野鸡族。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p017·原文件第22行", "note": "原文：十一月，辛未，徙保义节度使折从阮为静难节度使，讨野鸡族。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f50b4839-763a-52d4-b316-a2f8b750f987", "subject_id": "8bdfdf84-d8a1-5030-8385-6581b2e625be", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》也记十一月辛未折从阮由陕州移镇邠州。", "citation": "《旧五代史》卷一百十二，段落 jiu-wudaishi-205deb4a7860-p002679；EPUB电子本，纸本及异文待核", "note": "原文：辛未，陜州折從阮移鎮邠州。；核对说明：陕州与邠州分别对应保义、静难治所，用于印证同一次移镇，不将两种名称当作两次任职。", "status": "draft", "id": "726cf584-8deb-51be-aa21-005838161b3e", "subject_id": "ed070086-92f8-56e7-91a2-9d0bdb869e20", "source_id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"subject_table": "event", "field_path": "description", "claim_text": "郭威减少牛皮征收三分之二，每十顷田征一张，余皮准许自用和买卖。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：癸酉，敕：“约每岁民间所输牛皮，三分减二；计田十顷，税取一皮，馀听民自用及卖买，惟禁卖于敌国。”；核对说明：三分减二为减少原征收额的三分之二，不误写成减至原来的三分之二；仍有按田征收。", "status": "draft", "id": "18babc12-42f2-557f-a851-84e3dec13b0f", "subject_id": "9e45c1ce-ae45-58ca-b815-8bfb4f1d6040", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "952年十一月癸酉，《通鉴》纪日", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：癸酉，敕：“约每岁民间所输牛皮，三分减二；计田十顷，税取一皮，馀听民自用及卖买，惟禁卖于敌国。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "556cb2dc-7193-5ead-9e5a-c068d99c3c74", "subject_id": "9e45c1ce-ae45-58ca-b815-8bfb4f1d6040", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "郭威：减少牛皮征收并准许余皮自用买卖，但禁止卖给敌国。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：癸酉，敕：“约每岁民间所输牛皮，三分减二；计田十顷，税取一皮，馀听民自用及卖买，惟禁卖于敌国。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d8d01a1d-a277-54be-84ad-f44d49474892", "subject_id": "7f5d33e2-e655-57f3-878a-b7d648967f6d", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》补充每十顷纳连角皮一张，另规定黄牛、水牛筋额，犊子皮不在征收范围。", "citation": "《旧五代史》卷一百十二，段落 jiu-wudaishi-205deb4a7860-p002679；EPUB电子本，纸本及异文待核", "note": "原文：應天下所納牛皮，今將逐所納數，三分內減二分，其一分於人戶苗畝上配定。每秋夏苗共十頃納連角皮一張，其黃牛納幹筋四兩，水牛半斤，犢子皮不在納限。；核对说明：与减二分的规定印证；具体筋额是《旧五代史》敕文另载，不能扩成每种牛皮一律同额。", "status": "draft", "id": "864a8b21-fbe5-554d-9502-58351615d69f", "subject_id": "9e45c1ce-ae45-58ca-b815-8bfb4f1d6040", "source_id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "《旧五代史》将该牛皮新规诏令记在十一月甲戌。", "citation": "《旧五代史》卷一百十二，段落 jiu-wudaishi-205deb4a7860-p002679；EPUB电子本，纸本及异文待核", "note": "原文：甲戌，詔曰：「累朝已來，用兵不息，；核对说明：甲戌与《通鉴》癸酉不同，可能是公布记录差异，保留各书纪日，不自行换算后覆盖。", "status": "draft", "id": "1ee5713b-1213-5e99-b83d-c4a4681e3562", "subject_id": "9e45c1ce-ae45-58ca-b815-8bfb4f1d6040", "source_id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》还记解除牛马驴骡皮筋角的禁制，仅禁止运往敌境，并撤去州县巡检牛皮人员。", "citation": "《旧五代史》卷一百十二，段落 jiu-wudaishi-205deb4a7860-p002679；EPUB电子本，纸本及异文待核", "note": "原文：牛馬驢騾皮筋角，今後官中更不禁斷，只不得將出化外敵境。州縣先置巡檢牛皮節級並停。；核对说明：作为敕令范围的独立补充，不将一切动物产品或一般对外贸易都认定为解禁。", "status": "draft", "id": "71999ba9-fd1c-5aff-85a6-8090984a81eb", "subject_id": "9e45c1ce-ae45-58ca-b815-8bfb4f1d6040", "source_id": "5eb3eaa3-e3ee-586e-95c5-890b977c00aa"}, {"subject_table": "event", "field_path": "description", "claim_text": "此前战争期间禁止民间买卖牛皮，要求送官并支付价款。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：先是，兵兴以来，禁民私卖买牛皮，悉令输官受直。；核对说明：受直是获得价款，与后续停止补偿的制度分开，不归作952年首次立法。", "status": "draft", "id": "26f4eb61-5d48-5e93-b00b-52beb0d45ab6", "subject_id": "e494628c-692e-5da3-a4f3-ec4851bde6d0", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "此前战争时期的制度回述，起始年未载", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：先是，兵兴以来，禁民私卖买牛皮，悉令输官受直。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "a3eee7da-d18e-5be3-a0a5-480c26e3194c", "subject_id": "e494628c-692e-5da3-a4f3-ec4851bde6d0", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "description", "claim_text": "唐明宗时官府对征收牛皮只以盐偿付。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：唐明宗之世，有司止偿以盐；；核对说明：只以盐补偿是《资治通鉴》所记，不等同全额现金价款；不自行补交易数量。", "status": "draft", "id": "e3731e8a-1e9e-56fd-be79-61dacafb87d1", "subject_id": "f4efd534-0e2a-513f-8298-73812d5f4443", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "后唐明宗在位时期的回述，本段未给具体实施年", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：唐明宗之世，有司止偿以盐；；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "8520f096-cb6f-50d0-90ab-053d3eab2fa1", "subject_id": "f4efd534-0e2a-513f-8298-73812d5f4443", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "description", "claim_text": "后晋天福年间，征收牛皮连盐补偿也不再支付。", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y0952-p018·原文件第23行", "note": "原文：晋天福中，并盐不给。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "dff8bc87-db40-501a-b376-06badacc832c", "subject_id": "b67b3ae5-0d57-5d1b-9ce0-b657bd271fcb", "source_id": "259474f3-6192-5096-9244-e7a279478f03"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "后晋天福年间的回述，具体实施年未载", "citation": "卷291·广顺二年（952年十一月至十二月及相关追述）·zztj-v291-y09